def transform(grid):
    """Extend colored pluses along their row and column, stopping at gray arms."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color not in (0, 3) and all(
                grid[rr][cc] == 3
                for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            ):
                centers.append((r, c, color))

    out = [row[:] for row in grid]
    # Paint horizontal rays first. The plus's own gray arm is traversed;
    # any further gray cell blocks the ray. Only original blank cells change.
    for r, c, color in centers:
        for dc in (-1, 1):
            cc = c + dc
            while 0 <= cc < w and grid[r][cc] == 3:
                cc += dc
            while 0 <= cc < w and grid[r][cc] != 3:
                if grid[r][cc] == 0:
                    out[r][cc] = color
                cc += dc
    # Paint vertical rays second, so vertical colors win where newly painted
    # horizontal and vertical lines intersect.
    for r, c, color in centers:
        for dr in (-1, 1):
            rr = r + dr
            while 0 <= rr < h and grid[rr][c] == 3:
                rr += dr
            while 0 <= rr < h and grid[rr][c] != 3:
                if grid[rr][c] == 0:
                    out[rr][c] = color
                rr += dr
    return out
